const accents=["#c9ff3d","#c9ff3d","#c9ff3d","#ffd052","#ffd052","#ff6a3d","#4774ff","#4774ff","#ff6a3d","#ff9d69","#45c8ef","#d8a759","#b695ff","#ff8eb6","#58d4b0","#ff875f","#74a3ff","#b695ff","#ff554f","#c9ff3d"];
TASK_FAMILIES.forEach(f=>f.tasks.forEach((t,i)=>{t.id=`F${String(f.n).padStart(2,"0")}-T${String(i+1).padStart(2,"0")}`;t.storageId=t.id}));

const INSTANCE_VARIANTS=[
  {id:"I01",zh:"标准",en:""},{id:"I02",zh:"红色",en:"red"},{id:"I03",zh:"蓝色",en:"blue"},{id:"I04",zh:"黄色",en:"yellow"},
  {id:"I05",zh:"绿色",en:"green"},{id:"I06",zh:"橙色",en:"orange"},{id:"I07",zh:"黑色",en:"black"},{id:"I08",zh:"白色",en:"white"},
  {id:"I09",zh:"灰色",en:"gray"},{id:"I10",zh:"透明",en:"transparent"},{id:"I11",zh:"大号红色",en:"large red"},{id:"I12",zh:"小号红色",en:"small red"},
  {id:"I13",zh:"大号蓝色",en:"large blue"},{id:"I14",zh:"小号蓝色",en:"small blue"},{id:"I15",zh:"高型黄色",en:"tall yellow"},{id:"I16",zh:"矮型黄色",en:"short yellow"},
  {id:"I17",zh:"宽型绿色",en:"wide green"},{id:"I18",zh:"窄型绿色",en:"narrow green"},{id:"I19",zh:"条纹白色",en:"striped white"},{id:"I20",zh:"标签灰色",en:"labeled gray"}
];

const el={grid:document.querySelector("#familyGrid"),empty:document.querySelector("#emptyState"),search:document.querySelector("#searchInput"),scene:document.querySelector("#sceneFilter"),reset:document.querySelector("#resetBtn"),dialog:document.querySelector("#familyDialog"),dialogContent:document.querySelector("#dialogContent"),close:document.querySelector("#dialogClose"),sceneDialog:document.querySelector("#sceneDialog"),sceneDialogContent:document.querySelector("#sceneDialogContent"),sceneDialogClose:document.querySelector("#sceneDialogClose")};
let editorPassword="";
let sharedTaskOverrides={};
try{editorPassword=sessionStorage.getItem("unitree-material-editor-password")||""}catch{}
const SHARED_API_BASE=location.hostname.endsWith("github.io")?"https://unitree-atomic-task-library.smokyocean8.chatgpt.site":"";
SCENES.forEach(scene=>el.scene.insertAdjacentHTML("beforeend",`<option value="${scene}">${scene}</option>`));

function taskMatches(f,t){if(t.deleted)return false;const q=el.search.value.trim().toLowerCase();const text=[f.zh,f.en,f.desc,...f.examples,t.name,t.scene,t.items,t.primaryObject,t.description,t.prompt].join(" ").toLowerCase();return(el.scene.value==="all"||t.scene===el.scene.value)&&(!q||text.includes(q));}
function visibleFamilies(){const filtering=el.scene.value!=="all"||Boolean(el.search.value.trim());return TASK_FAMILIES.map(f=>({...f,matched:f.tasks.filter(t=>taskMatches(f,t))})).filter(f=>!filtering||f.matched.length);}
function escapeHtml(v){return String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function splitTaskItems(items){const parts=String(items).split(/[、，,]/).map(v=>v.trim()).filter(Boolean);return{primary:parts[0]||"目标物体",parts}}
function primaryObject(task){return task.primaryObject||splitTaskItems(task.items).primary}
function fixedReferences(task){if(task.fixedObjects)return task.fixedObjects;const {parts}=splitTaskItems(task.items),primary=primaryObject(task);let removed=false;const references=parts.filter(part=>{if(!removed&&(part.includes(primary)||primary.includes(part))){removed=true;return false}return true});if(!removed)references.shift();return references.join("、")||"无固定参照物"}
function instanceObject(task,variant){const primary=primaryObject(task);return variant.en?`${variant.zh}${primary}`:primary}
function instanceOptions(task,instances=null){const list=instances?.length?instances:INSTANCE_VARIANTS.map(variant=>({id:variant.id,name:instanceObject(task,variant)}));return list.map((instance,index)=>`<option value="${index}">${escapeHtml(instance.name||"未命名实例")}</option>`).join("")}
function taskOverridesStorageKey(){return"unitree-task-overrides"}
function normalizeTaskOverrides(value){if(!value||typeof value!=="object"||Array.isArray(value))return{};return Object.fromEntries(Object.entries(value).filter(([id,item])=>/^F\d{2}-(?:T\d{2,}|C\d{3})$/.test(id)&&item&&typeof item==="object").map(([id,item])=>[id,item.deleted?{deleted:true}:{name:String(item.name||"").trim(),description:String(item.description||"").trim(),prompt:String(item.prompt||"").trim(),...(item.custom?{custom:true,family:Number(item.family||id.slice(1,3)),scene:String(item.scene||"").trim(),primaryObject:String(item.primaryObject||"").trim()}: {})}]))}
async function readTaskOverrides(){try{const response=await fetch(`${SHARED_API_BASE}/api/tasks`,{cache:"no-store"});if(response.ok){const payload=await response.json(),tasks=normalizeTaskOverrides(payload.tasks);try{localStorage.setItem(taskOverridesStorageKey(),JSON.stringify(tasks))}catch{}return tasks}}catch{}try{return normalizeTaskOverrides(JSON.parse(localStorage.getItem(taskOverridesStorageKey())||"{}"))}catch{return{}}}
function syncCustomTasks(overrides){TASK_FAMILIES.forEach(f=>{f.tasks=f.tasks.filter(task=>!task.custom);f.tasks.forEach(task=>{task.storageId=task.storageId||task.id;task.deleted=Boolean(overrides[task.storageId]?.deleted)})});Object.entries(overrides).filter(([,task])=>task.custom).sort(([a],[b])=>a.localeCompare(b)).forEach(([storageId,task])=>{const family=TASK_FAMILIES.find(f=>f.n===task.family);if(family&&task.scene&&task.primaryObject)family.tasks.push({id:storageId,storageId,custom:true,name:task.name,description:task.description,prompt:task.prompt,scene:task.scene,items:task.primaryObject,primaryObject:task.primaryObject})});TASK_FAMILIES.forEach(f=>{let index=0;f.tasks.forEach(task=>{if(!task.deleted)task.id=`F${String(f.n).padStart(2,"0")}-T${String(++index).padStart(2,"0")}`})})}
async function writeTaskOverride(id,task,overrides){const full={...(overrides[id]||{}),...task};overrides[id]=full;sharedTaskOverrides=overrides;try{localStorage.setItem(taskOverridesStorageKey(),JSON.stringify(overrides))}catch{}try{const response=await fetch(`${SHARED_API_BASE}/api/tasks`,{method:"PUT",headers:{"content-type":"application/json","x-editor-password":editorPassword},body:JSON.stringify({id,...full})});if(response.status===401){editorPassword="";try{sessionStorage.removeItem("unitree-material-editor-password")}catch{}return"unauthorized"}return response.ok}catch{return"offline"}}
async function createCustomTask(family,task){try{const response=await fetch(`${SHARED_API_BASE}/api/tasks`,{method:"POST",headers:{"content-type":"application/json","x-editor-password":editorPassword},body:JSON.stringify({family,...task})});if(response.status===401){editorPassword="";try{sessionStorage.removeItem("unitree-material-editor-password")}catch{}return{status:"unauthorized"}}if(!response.ok)return{status:"error"};const payload=await response.json();sharedTaskOverrides[payload.id]=payload.task;try{localStorage.setItem(taskOverridesStorageKey(),JSON.stringify(sharedTaskOverrides))}catch{}syncCustomTasks(sharedTaskOverrides);return{status:"ok",id:payload.id}}catch{return{status:"offline"}}}
async function deleteAtomicTask(task){const storageId=task.storageId||task.id;try{const response=await fetch(`${SHARED_API_BASE}/api/tasks`,{method:"DELETE",headers:{"content-type":"application/json","x-editor-password":editorPassword},body:JSON.stringify({id:storageId,base:!task.custom})});if(response.status===401){editorPassword="";try{sessionStorage.removeItem("unitree-material-editor-password")}catch{}return"unauthorized"}if(!response.ok)return"error";if(task.custom)delete sharedTaskOverrides[storageId];else sharedTaskOverrides[storageId]={deleted:true};try{localStorage.setItem(taskOverridesStorageKey(),JSON.stringify(sharedTaskOverrides))}catch{}syncCustomTasks(sharedTaskOverrides);return"ok"}catch{return"offline"}}

function render(){const list=visibleFamilies();el.grid.innerHTML="";el.empty.hidden=list.length!==0;list.forEach(f=>{const card=document.createElement("article");card.className="family-card";card.style.setProperty("--accent",accents[f.n-1]);card.tabIndex=0;card.setAttribute("role","button");card.setAttribute("aria-label",`查看 ${f.zh} 的任务`);card.innerHTML=`<span class="family-number">FAMILY ${String(f.n).padStart(2,"0")}</span><h3>${escapeHtml(f.zh)}</h3><span class="family-en">${escapeHtml(f.en)}</span><p class="family-desc">${escapeHtml(f.desc)}</p><div class="family-bottom"><strong>${f.tasks.filter(task=>!task.deleted).length} TASKS</strong><b>查看任务 →</b></div>`;card.addEventListener("click",()=>openFamily(f));card.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();openFamily(f)}});el.grid.appendChild(card)});}

async function sceneMaterials(sceneName){const card=[...document.querySelectorAll(".scene-card")].find(item=>item.querySelector("h3").textContent.trim()===sceneName);if(!card)return[];const baseItems=(card.dataset.materials||"").split(/[、，,]/).map(v=>v.trim()).filter(Boolean),items=[...new Set([...baseItems,...requiredSceneMaterials(sceneName)])];return restoreRequiredSceneMaterials(await readSceneMaterials(sceneName,items),items)}
async function openFamily(f){
  const taskOverrides=await readTaskOverrides();sharedTaskOverrides=taskOverrides;syncCustomTasks(taskOverrides);
  const sourceFamily=TASK_FAMILIES.find(item=>item.n===f.n)||f,tasks=sourceFamily.tasks.filter(task=>taskMatches(sourceFamily,task));
  const sceneEntries=await Promise.all([...new Set(tasks.map(task=>task.scene))].map(async scene=>[scene,await sceneMaterials(scene)]));
  const sceneMap=new Map(sceneEntries);
  const taskMaterials=tasks.map(task=>{const key=primaryObject(task),materials=sceneMap.get(task.scene)||[];return materials.find(material=>material.key===key)||materials.find(material=>material.name===key)||null});
  const taskValue=t=>{const saved=taskOverrides[t.storageId||t.id]||{};return{name:saved.name||t.name,description:saved.description||t.description,prompt:saved.prompt||t.prompt}};
  const rows=tasks.map((t,index)=>{const value=taskValue(t);return`<article class="task-row" data-task-id="${t.id}"><div class="task-row-index">${t.id}</div><div class="task-main"><div class="task-title-line"><input class="task-edit task-name-edit" value="${escapeHtml(value.name)}" aria-label="${t.id} 任务名" readonly><button type="button" class="task-delete" aria-label="删除 ${t.id}" title="删除任务">${trashIcon()}</button></div><div class="task-badges"><span class="badge">${escapeHtml(f.zh)}</span><span class="badge">${escapeHtml(t.scene)}</span></div><div class="task-definition"><label class="detail task-goal-detail"><small>任务目标</small><textarea class="task-edit task-goal-edit" aria-label="${t.id} 任务目标" rows="2" readonly>${escapeHtml(value.description)}</textarea></label><div class="detail instance-detail"><button type="button" class="task-instance-jump" aria-label="定位到 ${escapeHtml(t.scene)} 的 ${escapeHtml(primaryObject(t))} 物料"><span>物品实例</span><i>↗</i></button><label class="instance-select"><select aria-label="选择 ${escapeHtml(value.name)} 的物品实例">${instanceOptions(t,taskMaterials[index]?.instances)}</select><i>⌄</i></label></div></div><label class="prompt"><strong>语言指令</strong><textarea class="task-edit task-prompt-edit" aria-label="${t.id} 语言指令" rows="1" readonly>${escapeHtml(value.prompt)}</textarea></label></div></article>`}).join("");
  const sceneOptions=SCENES.map(scene=>`<option value="${escapeHtml(scene)}">${escapeHtml(scene)}</option>`).join("");
  el.dialogContent.innerHTML=`<div class="dialog-body task-dialog-body"><span class="dialog-kicker">FAMILY ${String(f.n).padStart(2,"0")} · ${sourceFamily.tasks.filter(task=>!task.deleted).length} TASKS</span><h2>${escapeHtml(f.zh)}</h2><p class="dialog-summary"><strong>${escapeHtml(f.en)}</strong> — ${escapeHtml(f.desc)}</p><div class="task-edit-toolbar"><span class="task-editor-mode-state"></span><button type="button" class="task-editor-unlock"></button><button type="button" class="task-add-trigger">＋ 添加任务</button><span class="task-save-status" aria-live="polite"></span></div><div class="task-add-panel" hidden><label><small>任务名</small><input class="new-task-name" placeholder="填写原子任务名称"></label><label><small>任务目标</small><textarea class="new-task-goal" rows="2" placeholder="描述任务需要达到的状态变化"></textarea></label><label><small>语言指令</small><input class="new-task-prompt" placeholder="例如：pick up the cup"></label><label><small>场景</small><select class="new-task-scene">${sceneOptions}</select></label><label><small>物料名</small><input class="new-task-object" placeholder="填写主交互物体类别"></label><div class="task-add-actions"><button type="button" class="task-add-cancel">取消</button><button type="button" class="task-add-save">创建任务</button></div></div><div class="task-list">${rows}</div></div>`;
  const body=el.dialogContent.querySelector(".task-dialog-body"),modeState=body.querySelector(".task-editor-mode-state"),unlock=body.querySelector(".task-editor-unlock"),addTrigger=body.querySelector(".task-add-trigger"),addPanel=body.querySelector(".task-add-panel"),status=body.querySelector(".task-save-status");let editing=Boolean(editorPassword),saveTimers=new Map();
  const setTaskEditing=enabled=>{editing=enabled;body.classList.toggle("is-editing",enabled);modeState.textContent=enabled?"编辑模式 · 自动保存":"只读模式";unlock.textContent=enabled?"已解锁":"输入编辑密码";unlock.disabled=enabled;addTrigger.disabled=!enabled;body.querySelectorAll(".task-edit").forEach(field=>field.readOnly=!enabled);body.querySelectorAll(".task-delete").forEach(button=>button.disabled=!enabled)};
  setTaskEditing(editing);
  unlock.addEventListener("click",async()=>{const password=window.prompt("请输入团队编辑密码");if(!password)return;unlock.disabled=true;unlock.textContent="验证中…";if(await verifyEditorPassword(password)){editorPassword=password;try{sessionStorage.setItem("unitree-material-editor-password",password)}catch{}setTaskEditing(true);status.textContent="已进入编辑模式 · 自动保存已开启"}else{setTaskEditing(false);status.textContent="密码错误，请重试"}});
  addTrigger.addEventListener("click",()=>{if(!editing)return;addPanel.hidden=false;addTrigger.disabled=true;addPanel.querySelector(".new-task-name").focus()});
  addPanel.querySelector(".task-add-cancel").addEventListener("click",()=>{addPanel.hidden=true;addTrigger.disabled=!editing});
  addPanel.querySelector(".task-add-save").addEventListener("click",async()=>{const task={name:addPanel.querySelector(".new-task-name").value.trim(),description:addPanel.querySelector(".new-task-goal").value.trim(),prompt:addPanel.querySelector(".new-task-prompt").value.trim(),scene:addPanel.querySelector(".new-task-scene").value,primaryObject:addPanel.querySelector(".new-task-object").value.trim()};if(Object.values(task).some(value=>!value)){status.textContent="请完整填写新增任务的全部字段";return}status.textContent="正在创建任务…";const result=await createCustomTask(f.n,task);if(result.status==="ok"){status.textContent=`${result.id} 已创建`;render();closeDialog();await openFamily(TASK_FAMILIES.find(item=>item.n===f.n))}else if(result.status==="unauthorized"){setTaskEditing(false);status.textContent="编辑密码已失效，请重新解锁"}else status.textContent="创建失败，请检查网络后重试"});
  el.dialogContent.querySelectorAll(".task-row").forEach((row,index)=>{
    const task=tasks[index],storageId=task.storageId||task.id,material=taskMaterials[index],select=row.querySelector(".instance-select select"),jump=row.querySelector(".task-instance-jump"),remove=row.querySelector(".task-delete"),fields=[...row.querySelectorAll(".task-edit")];
    jump.addEventListener("click",()=>navigateToTaskMaterial(task,Number(select.value),material?.key||primaryObject(task)));
    remove.addEventListener("click",async()=>{if(!editing||!window.confirm(`确定删除 ${task.id}「${row.querySelector(".task-name-edit").value}」吗？删除后本类别任务编号将自动重排。`))return;status.textContent=`${task.id} 正在删除…`;const result=await deleteAtomicTask(task);if(result==="ok"){render();closeDialog();await openFamily(TASK_FAMILIES.find(item=>item.n===f.n))}else if(result==="unauthorized"){setTaskEditing(false);status.textContent="编辑密码已失效，请重新解锁"}else status.textContent="删除失败，请检查网络后重试"});
    fields.forEach(field=>field.addEventListener("input",()=>{
      if(!editing)return;
      clearTimeout(saveTimers.get(storageId));
      status.textContent=`${task.id} 等待自动保存…`;
      saveTimers.set(storageId,setTimeout(async()=>{
        const value={name:row.querySelector(".task-name-edit").value.trim(),description:row.querySelector(".task-goal-edit").value.trim(),prompt:row.querySelector(".task-prompt-edit").value.trim()};
        if(!value.name||!value.description||!value.prompt){status.textContent=`${task.id} 三个字段均不能为空`;return}
        status.textContent=`${task.id} 正在保存…`;
        const result=await writeTaskOverride(storageId,value,taskOverrides);
        if(result===true)status.textContent=`${task.id} 已自动保存 ${new Date().toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"})}`;
        else if(result==="unauthorized"){setTaskEditing(false);status.textContent="编辑密码已失效，请重新解锁"}
        else status.textContent="网络异常，已暂存于当前浏览器";
      },700));
    }));
  });
  el.dialog.showModal();document.body.classList.add("no-scroll");
}
function closeDialog(){el.dialog.close();document.body.classList.remove("no-scroll")}
function navigateToTaskMaterial(task,instanceIndex,materialKey=primaryObject(task)){const cards=[...document.querySelectorAll(".scene-card")],index=cards.findIndex(card=>card.querySelector("h3").textContent.trim()===task.scene);if(index<0)return;const card=cards[index];closeDialog();card.scrollIntoView({behavior:"smooth",block:"center"});setTimeout(()=>openSceneDetail(card,index,{materialKey,materialName:primaryObject(task),instanceIndex}),420)}
function sceneStorageKey(sceneName){return `unitree-scene-material-links:${sceneName}`}
function defaultMaterialInstances(category){const base=String(category||"未命名物料").trim()||"未命名物料";return INSTANCE_VARIANTS.map(variant=>({id:variant.id,name:variant.en?`${variant.zh}${base}`:base,url:""}))}
function normalizeSceneMaterials(saved,defaults){if(Array.isArray(saved))return saved.map((item,index)=>{const name=String(item?.name||defaults[index]||`物料类别 ${index+1}`).trim(),key=String(item?.key||(defaults.includes(name)?name:defaults[index])||name).trim();if(Array.isArray(item?.instances)){const instances=item.instances.map((instance,i)=>({id:instance.id||`I${String(i+1).padStart(2,"0")}`,name:String(instance.name||`${name}实例 ${i+1}`).trim(),url:String(instance.url||"").trim()}));return{key,name,instances:instances.length?instances:defaultMaterialInstances(name)}}const instances=defaultMaterialInstances(name);if(item?.url)instances[0].url=String(item.url).trim();return{key,name,instances}});if(saved&&typeof saved==="object")return defaults.map(name=>{const instances=defaultMaterialInstances(name);if(saved[name])instances[0].url=String(saved[name]).trim();return{key:name,name,instances}});return defaults.map(name=>({key:name,name,instances:defaultMaterialInstances(name)}))}
async function readSceneMaterials(sceneName,defaults){try{const response=await fetch(`${SHARED_API_BASE}/api/materials/${encodeURIComponent(sceneName)}`,{cache:"no-store"});if(response.ok){const payload=await response.json();if(Array.isArray(payload.materials))return normalizeSceneMaterials(payload.materials,defaults)}}catch{}try{return normalizeSceneMaterials(JSON.parse(localStorage.getItem(sceneStorageKey(sceneName))||"null"),defaults)}catch{return normalizeSceneMaterials(null,defaults)}}
function requiredSceneMaterials(sceneName){return [...new Set(TASK_FAMILIES.flatMap(f=>f.tasks).filter(task=>!task.deleted&&task.scene===sceneName).map(task=>primaryObject(task)).filter(Boolean))]}
function restoreRequiredSceneMaterials(materials,defaults){const existing=new Set(materials.map(material=>material.key||material.name));defaults.forEach(name=>{if(!existing.has(name))materials.push({key:name,name,instances:defaultMaterialInstances(name)})});return materials}
async function writeSceneMaterials(sceneName,materials){try{localStorage.setItem(sceneStorageKey(sceneName),JSON.stringify(materials))}catch{}try{const response=await fetch(`${SHARED_API_BASE}/api/materials/${encodeURIComponent(sceneName)}`,{method:"PUT",headers:{"content-type":"application/json","x-editor-password":editorPassword},body:JSON.stringify({materials})});if(response.status===401){editorPassword="";try{sessionStorage.removeItem("unitree-material-editor-password")}catch{}return"unauthorized"}return response.ok}catch{return"offline"}}
async function verifyEditorPassword(password){try{const response=await fetch(`${SHARED_API_BASE}/api/editor-auth`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({password})});return response.ok}catch{return false}}
function safeMaterialUrl(value){const url=String(value||"").trim();return /^https?:\/\//i.test(url)?url:"#"}
function sceneText(card,selector,label){return card.querySelector(selector).textContent.trim().replace(new RegExp(`^${label}`),"").trim().replace(/。$/,"")}
function trashIcon(){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3m-8 0 1 13h8l1-13M10 11v5m4-5v5"/></svg>`}
function editIcon(){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20h4l11-11-4-4L4 16v4Zm9-13 4 4"/></svg>`}
function checkIcon(){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg>`}
function materialLinkControl(instance){const raw=String(instance.url||"").trim(),url=safeMaterialUrl(raw),linked=url!=="#";return `<div class="material-link-cell"><input class="material-url${linked?" is-linked":""}" type="url" inputmode="url" value="${escapeHtml(raw)}" placeholder="https://…" aria-label="物料链接"><a class="material-link${linked?" is-visible":""}" href="${escapeHtml(url)}" target="_blank" rel="noreferrer">${escapeHtml(raw)}</a><button type="button" class="material-link-edit${linked?" is-visible":""}">修改</button></div>`}
function materialInstanceOptions(material,selected=0){return material.instances.map((instance,i)=>`<option value="${i}"${i===selected?" selected":""}>${escapeHtml(instance.name||"未命名实例")}</option>`).join("")}
function materialInstanceEditor(material,selected=0){const instance=material.instances[selected];if(!instance)return`<div class="material-instance-empty"><span>该物料暂无实例</span><button type="button" class="material-instance-add">＋ 添加实例</button></div>`;return `<div class="material-instance-module" data-instance-index="${selected}"><label><small>物料链接</small>${materialLinkControl(instance)}</label></div>`}
function materialCategoryCard(material,i){const instance=material.instances[0];return `<article class="material-category" data-category-index="${i}"><header><span class="material-index">${String(i+1).padStart(2,"0")}</span><label><small>物料名</small><input class="material-category-name" value="${escapeHtml(material.name||"")}" placeholder="填写物料名" aria-label="物料名"></label><label><small>实例</small><div class="material-instance-control"><select class="material-instance-select" aria-label="选择 ${escapeHtml(material.name||"物料")} 的实例">${materialInstanceOptions(material)}</select><button type="button" class="material-instance-edit-trigger" aria-label="修改当前实例名称" title="修改实例名称">${editIcon()}</button><div class="material-instance-edit-box" hidden><input class="material-instance-edit-input" value="${escapeHtml(instance?.name||"")}" aria-label="修改实例名称"><button type="button" class="material-instance-edit-save" aria-label="保存实例名称" title="保存">${checkIcon()}</button></div></div></label><button type="button" class="material-instance-add icon-add" aria-label="添加实例" title="添加实例"${material.instances.length>=20?" disabled":""}>＋</button><button type="button" class="material-category-delete icon-delete" aria-label="删除 ${escapeHtml(material.name||"该物料")}" title="删除该物料">${trashIcon()}</button></header><div class="material-instance-editor">${materialInstanceEditor(material)}</div></article>`}
async function openSceneDetail(card,index,focus=null){
  const sceneName=card.querySelector("h3").textContent.trim();
  const baseItems=(card.dataset.materials||"").split(/[、，,]/).map(v=>v.trim()).filter(Boolean);
  const items=[...new Set([...baseItems,...requiredSceneMaterials(sceneName)])];
  let materials=restoreRequiredSceneMaterials(await readSceneMaterials(sceneName,items),items);
  el.sceneDialogContent.innerHTML=`<div class="dialog-body scene-dialog-body"><span class="dialog-kicker">SCENE ${String(index+1).padStart(2,"0")} · SHARED MATERIAL REGISTER</span><h2>${escapeHtml(sceneName)}</h2><div class="material-register-head"><div><strong>场景物料</strong><p>共享物料清单 · 修改后自动保存并同步给所有访问者</p></div><div class="editor-access"><span class="editor-mode-state"></span><button type="button" class="editor-unlock"></button></div></div><div class="material-register"></div><button type="button" class="material-add">＋ 添加物料</button><div class="material-actions"><p>公开浏览；输入团队编辑密码后可修改物料、实例及链接。</p><span class="material-save-status" aria-live="polite"></span></div></div>`;
  const register=el.sceneDialogContent.querySelector(".material-register");
  const status=el.sceneDialogContent.querySelector(".material-save-status");
  const modeState=el.sceneDialogContent.querySelector(".editor-mode-state");
  const unlockButton=el.sceneDialogContent.querySelector(".editor-unlock");
  const addMaterialButton=el.sceneDialogContent.querySelector(".material-add");
  let editing=Boolean(editorPassword),saveTimer=0;
  const setEditing=enabled=>{editing=enabled;modeState.textContent=enabled?"编辑模式 · 自动保存":"只读模式";unlockButton.textContent=enabled?"已解锁":"输入编辑密码";unlockButton.disabled=enabled;el.sceneDialogContent.classList.toggle("is-editing",enabled);register.querySelectorAll(".material-category").forEach((categoryCard,categoryIndex)=>{categoryCard.querySelectorAll(".material-category-name,.material-url,.material-instance-edit-trigger,.material-instance-edit-save,.material-category-delete,.material-link-edit").forEach(control=>control.disabled=!enabled);const add=categoryCard.querySelector(".material-instance-add");if(add)add.disabled=!enabled||(materials[categoryIndex]?.instances.length||0)>=20});addMaterialButton.disabled=!enabled};
  const normalizedMaterials=()=>materials.map(material=>({key:String(material.key||material.name||"").trim(),name:String(material.name||"").trim(),instances:material.instances.map(instance=>({id:instance.id,name:String(instance.name||"").trim(),url:String(instance.url||"").trim()}))})).filter(material=>material.name||material.instances.length);
  const saveNow=async()=>{if(!editing)return;materials=normalizedMaterials();status.textContent="正在保存…";const result=await writeSceneMaterials(sceneName,materials);if(result===true){status.textContent=`已自动保存 ${new Date().toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"})}`}else if(result==="unauthorized"){setEditing(false);status.textContent="编辑密码已失效，请重新解锁"}else{status.textContent="网络异常，已暂存于当前浏览器"}};
  const scheduleSave=()=>{if(!editing)return;clearTimeout(saveTimer);status.textContent="等待自动保存…";saveTimer=setTimeout(saveNow,700)};
  const renderCategories=()=>{register.innerHTML=materials.map(materialCategoryCard).join("");setEditing(editing)};
  const renderEditor=(categoryCard,selected)=>{const categoryIndex=Number(categoryCard.dataset.categoryIndex),material=materials[categoryIndex],safeIndex=Math.max(0,Math.min(selected,material.instances.length-1));categoryCard.querySelector(".material-instance-editor").innerHTML=materialInstanceEditor(material,safeIndex);const selector=categoryCard.querySelector(".material-instance-select"),editBox=categoryCard.querySelector(".material-instance-edit-box"),editInput=categoryCard.querySelector(".material-instance-edit-input"),editTrigger=categoryCard.querySelector(".material-instance-edit-trigger");selector.innerHTML=materialInstanceOptions(material,safeIndex);editInput.value=material.instances[safeIndex]?.name||"";selector.hidden=false;editTrigger.hidden=false;editBox.hidden=true;setEditing(editing)};
  const activateLink=input=>{const cell=input.closest(".material-link-cell"),link=cell.querySelector(".material-link"),edit=cell.querySelector(".material-link-edit"),raw=input.value.trim(),url=safeMaterialUrl(raw);if(url==="#")return;link.href=url;link.textContent=raw;input.classList.add("is-linked");link.classList.add("is-visible");edit.classList.add("is-visible")};
  renderCategories();
  register.addEventListener("input",e=>{const categoryCard=e.target.closest(".material-category");if(!categoryCard||!editing)return;const categoryIndex=Number(categoryCard.dataset.categoryIndex),material=materials[categoryIndex];if(e.target.classList.contains("material-category-name"))material.name=e.target.value;if(e.target.classList.contains("material-url")){const instanceIndex=Number(e.target.closest(".material-instance-module").dataset.instanceIndex);material.instances[instanceIndex].url=e.target.value}scheduleSave()});
  register.addEventListener("change",e=>{if(e.target.classList.contains("material-instance-select"))renderEditor(e.target.closest(".material-category"),Number(e.target.value))});
  register.addEventListener("focusout",e=>{if(e.target.classList.contains("material-url"))activateLink(e.target)});
  register.addEventListener("keydown",e=>{if(e.target.classList.contains("material-url")&&e.key==="Enter"){e.preventDefault();activateLink(e.target)}if(e.target.classList.contains("material-instance-edit-input")&&e.key==="Enter"){e.preventDefault();e.target.closest(".material-instance-control").querySelector(".material-instance-edit-save").click()}if(e.target.classList.contains("material-instance-edit-input")&&e.key==="Escape"){e.preventDefault();renderEditor(e.target.closest(".material-category"),Number(e.target.closest(".material-category").querySelector(".material-instance-select").value))}});
  register.addEventListener("click",e=>{const categoryCard=e.target.closest(".material-category");if(!categoryCard)return;const categoryIndex=Number(categoryCard.dataset.categoryIndex),material=materials[categoryIndex];const edit=e.target.closest(".material-link-edit");if(edit&&editing){const cell=edit.closest(".material-link-cell"),input=cell.querySelector(".material-url");input.classList.remove("is-linked");cell.querySelector(".material-link").classList.remove("is-visible");edit.classList.remove("is-visible");input.focus();input.select();return}if(e.target.closest(".material-instance-edit-trigger")&&editing){const selector=categoryCard.querySelector(".material-instance-select"),editBox=categoryCard.querySelector(".material-instance-edit-box"),editInput=categoryCard.querySelector(".material-instance-edit-input");selector.hidden=true;e.target.closest(".material-instance-edit-trigger").hidden=true;editBox.hidden=false;editInput.value=material.instances[Number(selector.value)]?.name||"";editInput.focus();editInput.select();return}if(e.target.closest(".material-instance-edit-save")&&editing){const selector=categoryCard.querySelector(".material-instance-select"),selected=Number(selector.value),value=categoryCard.querySelector(".material-instance-edit-input").value.trim();if(material.instances[selected])material.instances[selected].name=value||"未命名实例";renderEditor(categoryCard,selected);scheduleSave();return}if(e.target.closest(".material-category-delete")&&editing){materials.splice(categoryIndex,1);renderCategories();scheduleSave();return}if(e.target.closest(".material-instance-add")&&editing){const used=new Set(material.instances.map(instance=>instance.id));let n=1;while(used.has(`I${String(n).padStart(2,"0")}`))n++;const id=`I${String(n).padStart(2,"0")}`;material.instances.push({id,name:`${material.name||"具体物料"}实例 ${String(n).padStart(2,"0")}`,url:""});renderEditor(categoryCard,material.instances.length-1);scheduleSave()}});
  addMaterialButton.addEventListener("click",()=>{if(!editing)return;const name="新物料",key=`custom-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;materials.push({key,name,instances:defaultMaterialInstances(name)});renderCategories();register.lastElementChild.querySelector(".material-category-name").focus();scheduleSave()});
  unlockButton.addEventListener("click",async()=>{const password=window.prompt("请输入团队编辑密码");if(!password)return;unlockButton.disabled=true;unlockButton.textContent="验证中…";if(await verifyEditorPassword(password)){editorPassword=password;try{sessionStorage.setItem("unitree-material-editor-password",password)}catch{}setEditing(true);status.textContent="已进入编辑模式 · 自动保存已开启"}else{setEditing(false);status.textContent="密码错误，请重试"}});
  el.sceneDialog.showModal();document.body.classList.add("no-scroll");
  if(focus){const materialIndex=materials.findIndex(material=>material.key===focus.materialKey||material.name===focus.materialName),target=register.querySelector(`[data-category-index="${materialIndex}"]`);if(target){renderEditor(target,focus.instanceIndex||0);requestAnimationFrame(()=>{target.scrollIntoView({behavior:"smooth",block:"center"});target.classList.add("material-focus-flash");setTimeout(()=>target.classList.remove("material-focus-flash"),2400)})}}
}
function closeSceneDialog(){el.sceneDialog.close();document.body.classList.remove("no-scroll")}
document.querySelectorAll(".scene-card").forEach((card,index)=>{const trigger=document.createElement("button");trigger.type="button";trigger.className="scene-detail-trigger";trigger.innerHTML="<span>物料配置</span><b>→</b>";trigger.addEventListener("click",()=>openSceneDetail(card,index));card.appendChild(trigger)});
function reset(){el.search.value="";el.scene.value="all";render()}
async function initializeTasks(){sharedTaskOverrides=await readTaskOverrides();syncCustomTasks(sharedTaskOverrides);render()}
initializeTasks();[el.search,el.scene].forEach(x=>x.addEventListener(x===el.search?"input":"change",render));el.reset.addEventListener("click",reset);el.close.addEventListener("click",closeDialog);el.dialog.addEventListener("click",e=>{if(e.target===el.dialog)closeDialog()});el.sceneDialogClose.addEventListener("click",closeSceneDialog);el.sceneDialog.addEventListener("click",e=>{if(e.target===el.sceneDialog)closeSceneDialog()});document.addEventListener("keydown",e=>{if(e.key==="Escape"){if(el.sceneDialog.open)closeSceneDialog();else if(el.dialog.open)closeDialog()}});
